export function solicitarUbicacion(timeoutMs,maxAgeMs){return new Promise(function(resolve,reject){if(!navigator.geolocation){reject(new Error("Geolocation no disponible en este navegador"));return}navigator.geolocation.getCurrentPosition(function(pos){resolve({lat:pos.coords.latitude,lng:pos.coords.longitude})},function(err){reject(err)},{enableHighAccuracy:false,timeout:timeoutMs,maximumAge:maxAgeMs})})}export function geolocationDisponible(){return!!navigator.geolocation}